height:18),const Text('التصنيفات',style:TextStyle(fontSize:19,fontWeight:FontWeight.w900)),SizedBox(height:47,child:ListView(scrollDirection:Axis.horizontal,children:['الكل','برغر','بيتزا','تاكوس','شاورما','حلويات','مشروبات'].map((x)=>Padding(padding:const EdgeInsets.only(left:7),child:ChoiceChip(label:Text(x),selected:cat==x,onSelected:(_)=>setState(()=>cat=x),selectedColor:p,side:BorderSide.none,labelStyle:TextStyle(color:cat==x?Colors.white:ink),showCheckmark:false))).toList())),const SizedBox(height:18),const Text('اختياراتنا لك ✨',style:TextStyle(fontSize:19,fontWeight:FontWeight.w900)),const SizedBox(height:12)]))),SliverPadding(padding:const EdgeInsets.fromLTRB(18,0,18,90),sliver:SliverGrid(delegate:SliverChildBuilderDelegate((c,i)=>Container(decoration:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(20),boxShadow:[BoxShadow(color:p.withValues(alpha: .05),blurRadius:15)]),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Expanded(child:Hero(tag:'food-${list[i].n}',child:Container(width:double.infinity,decoration:BoxDecoration(color:list[i].color,borderRadius:const BorderRadius.vertical(top:Radius.circular(20))),child:Center(child:Text(list[i].e,style:const TextStyle(fontSize:58))))),Padding(padding:const EdgeInsets.all(11),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(list[i].n,style:const TextStyle(fontWeight:FontWeight.w900),maxLines:1,overflow:TextOverflow.ellipsis),Text(list[i].s,style:const TextStyle(color:muted,fontSize:11)),Row(children:[Expanded(child:Text('${list[i].price} دج',style:const TextStyle(color:pd,fontWeight:FontWeight.w900))),IconButton.filled(onPressed:()=>add(list[i]),style:IconButton.styleFrom(backgroundColor:p,foregroundColor:Colors.white),icon:const Icon(Icons.add))])]))])),childCount:list.length),gridDelegate:const SliverGridDelegateWithFixedCrossAxisCount(crossAxisCount:2,crossAxisSpacing:12,mainAxisSpacing:12,childAspectRatio:.66))) ]),simple('المحلات',Icons.storefront)